30	// componentVariableType returns the type of the variable of which the value is a component.
31	// The type is derived from the outputs of the sub-program of the component into an ObjectType
32	func componentVariableType(program *Program) model.Type {
33		properties := map[string]model.Type{}
34		for _, node := range program.Nodes {
35			switch node := node.(type) {
36			case *OutputVariable:
37				if node.Value == nil {
38					continue
39				}
40	
41				switch nodeType := node.Value.Type().(type) {
42				case *model.OutputType:
43					// if the output variable is already an Output<T>, keep it as is
44					properties[node.LogicalName()] = nodeType
45				default:
46					// otherwise, wrap it as an output
47					properties[node.LogicalName()] = model.NewOutputType(nodeType)
48				}
49			}
50		}
51	
52		return model.NewObjectType(properties)
53	}
