61	func newComponentScopes(
62		root *model.Scope,
63		component *Component,
64		rangeKeyType model.Type,
65		rangeValueType model.Type,
66	) model.Scopes {
67		scopes := &componentScopes{
68			root:      root,
69			withRange: root,
70			component: component,
71		}
72	
73		if rangeValueType != nil {
74			properties := map[string]model.Type{
75				"value": rangeValueType,
76			}
77			if rangeKeyType != nil {
78				properties["key"] = rangeKeyType
79			}
80	
81			scopes.withRange = root.Push(syntax.None)
82			scopes.withRange.Define("range", &model.Variable{
83				Name:         "range",
84				VariableType: model.NewObjectType(properties),
85			})
86		}
87		return scopes
88	}
