124	// ComponentProgramBinderFromFileSystem returns the default component program binder which uses the file system
125	// to parse and bind PCL files into a program.
126	func ComponentProgramBinderFromFileSystem() ComponentProgramBinder {
127		return func(args ComponentProgramBinderArgs) (*Program, hcl.Diagnostics, error) {
128			var diagnostics hcl.Diagnostics
129			binderDirPath := args.BinderDirPath
130			componentSource := args.ComponentSource
131			nodeRange := args.ComponentNodeRange
132			loader := args.BinderLoader
133			// bind the component here as if it was a new program
134			// this becomes the DirPath for the new binder
135			componentSourceDir := filepath.Join(binderDirPath, componentSource)
136	
137			parser := syntax.NewParser()
138			// Load all .pp files in the components' directory
139			files, err := os.ReadDir(componentSourceDir)
140			if err != nil {
141				diagnostics = diagnostics.Append(errorf(nodeRange, "%s", err.Error()))
142				return nil, diagnostics, nil
143			}
144	
145			if len(files) == 0 {
146				diagnostics = diagnostics.Append(errorf(nodeRange, "no files found"))
147				return nil, diagnostics, nil
148			}
149	
150			for _, file := range files {
151				if file.IsDir() {
