// hookArgsType returns the type of the special `args` variable that is in scope when binding the
// `command` attribute of a hook block. It mirrors the shape of the arguments that are passed to a
// resource lifecycle hook at runtime.
func hookArgsType() model.Type {
	return model.NewObjectType(map[string]model.Type{
		"urn":         model.StringType,
		"id":          model.StringType,
		"name":        model.StringType,
		"type":        model.StringType,
		"new_inputs":  model.NewMapType(model.DynamicType),
		"old_inputs":  model.NewMapType(model.DynamicType),
		"new_outputs": model.NewMapType(model.DynamicType),
		"old_outputs": model.NewMapType(model.DynamicType),
	})
}

// hookCommandType is the type against which a hook's `command` attribute is type-checked. It is a
// list of strings, allowing for output-typed and safely-convertible primitive elements.
func hookCommandType() model.Type {
	return model.NewUnionType(
		model.NewListType(model.NewUnionType(model.NewOutputType(model.StringType), model.StringType)),
		model.NewOutputType(model.NewListType(model.StringType)),
	)
}

// hookScopes provides the scopes used when binding a hook block. The special `args` variable is only
// in scope when binding the `command` attribute; it is not visible when binding `onDryRun`.
type hookScopes struct {
	root    *model.Scope
	command *model.Scope
}

func newHookScopes(root *model.Scope) *hookScopes {
	command := root.Push(syntax.None)
	command.Define("args", &model.Variable{
		Name:         "args",
		VariableType: hookArgsType(),
	})
	return &hookScopes{
		root:    root,
		command: command,
	}
}

func (s *hookScopes) GetScopesForBlock(block *hclsyntax.Block) (model.Scopes, hcl.Diagnostics) {
	return model.StaticScope(s.root), nil
}

func (s *hookScopes) GetScopeForAttribute(attr *hclsyntax.Attribute) (*model.Scope, hcl.Diagnostics) {
	if attr.Name == "command" {
		return s.command, nil
	}
	return s.root, nil
}

func (b *binder) bindHook(node *Hook) hcl.Diagnostics {
	var diagnostics hcl.Diagnostics

	scopes := newHookScopes(b.root)
	block, blockDiags := model.BindBlock(node.syntax, scopes, b.tokens, b.options.modelOptions()...)
	diagnostics = append(diagnostics, blockDiags...)

	for _, item := range block.Body.Items {
		switch item := item.(type) {
		case *model.Attribute:
			switch item.Name {
			case "command":
				node.Command = item.Value
				commandType := hookCommandType()
				if commandType.ConversionFrom(item.Value.Type()) == model.NoConversion {
