func TestHookVerifyBasic(t *testing.T) {
	t.Parallel()
	source := `
hook "myHook" {
	command = [args.urn, args.id, args.name, args.type, "x"]
	onDryRun = true
}

resource randomPet "random:index/randomPet:RandomPet" {
	options {
		hooks = {
			beforeCreate = [myHook]
		}
	}
}
`
	program, diags, err := ParseAndBindProgram(t, source, "hook.pp")
	require.NoError(t, err)
	require.False(t, diags.HasErrors(), "unexpected diags: %v", diags)

	hooks := program.Hooks()
	require.Len(t, hooks, 1)
	assert.Equal(t, "myHook", hooks[0].Name())

	// find resource
	var resource *pcl.Resource
	for _, n := range program.Nodes {
		if r, ok := n.(*pcl.Resource); ok {
			resource = r
		}
	}
	require.NotNil(t, resource)
	require.NotNil(t, resource.Options)
	require.NotNil(t, resource.Options.Hooks)

	val, vdiags := resource.Options.Hooks.Evaluate(&hcl.EvalContext{})
	require.False(t, vdiags.HasErrors(), "eval diags: %v", vdiags)
	expected := cty.ObjectVal(map[string]cty.Value{
		"beforeCreate": cty.TupleVal([]cty.Value{cty.StringVal("myHook")}),
	})
	assert.True(t, val.RawEquals(expected), "got %#v", val)
}

